/**********************************************************
	cleans up all those nasty extra folders XSI leaves behind
12/14/2005 
stevek@valvesoftware.com
***********************************************************/

function folder_cleanup()
{
		path = activeproject.path;
    var fso = new ActiveXObject("Scripting.FileSystemObject"); 
    var folder = fso.GetFolder(path); 
    for (f = new Enumerator(folder.subFolders); !f.atEnd(); f.moveNext()) 
    { 
        sub_folder = f.item();
        size = sub_folder.size;
        if (size == 0)
        	{
        		logmessage (f.item() + " is empty and is being deleted");
        		sub_folder.Delete();
        	}
    } 
 }